source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    tracks = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 1:
                cells = [(r, c + 1), (r, c + 2)]
                end = (r - 1, c + 2)
            elif color == 2:
                cells = [(r, cc) for cc in range(c - 1, c - 4, -1)]
                end = (r, c - 4)
            elif color == 3:
                cells = [(rr, c) for rr in range(r + 1, r + 3)]
                end = (r + 3, c)
            elif color == 6:
                cells = [(rr, c) for rr in range(r - 1, r - 6, -1)]
                end = (r - 6, c)
            else:
                continue
            track = [(rr, cc) for rr, cc in cells + [end] if 0 <= rr < h and 0 <= cc < w]
            for rr, cc in track:
                if (rr, cc) == end:
                    out[rr][cc] = color
                elif out[rr][cc] == 0:
                    out[rr][cc] = 5
            tracks.append(track)
    crossings = set()
    for i in range(len(tracks)):
        for j in range(i + 1, len(tracks)):
            crossings.update(set(tracks[i]) & set(tracks[j]))
    for r, c in crossings:
        out[r][c] = 4
        rr, cc = r + 1, c - 1
        while 0 <= rr < h and 0 <= cc < w:
            out[rr][cc] = 4
            rr += 1
            cc -= 1
    return out
'''
